[dependencies]
parking_lot = "0.12"
hashbrown    = "0.14"
ahash        = "0.8"
```

```rust
use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash, Hasher};

use ahash::RandomState;
use hashbrown::hash_map::RawEntryMut;
use hashbrown::HashMap;
use parking_lot::{RwLock, RwLockReadGuard, RwLockWriteGuard};

// Pad each shard to its own cache line so reader-counter atomics on
// different shards don't false-share.
#[repr(align(64))]
struct Shard<K, V, S> {
    inner: RwLock<HashMap<K, V, S>>,
}

pub struct ShardedMap<K, V, S = RandomState> {
    shards: Box<[Shard<K, V, S>]>,
    hasher: S,
    shard_mask: usize,
}

impl<K, V> ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    pub fn new() -> Self {
        let n = std::thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1) * 4;
        Self::with_shards(n)
    }

    pub fn with_shards(shards: usize) -> Self {
        Self::with_shards_and_hasher(shards, RandomState::new())
    }
}

impl<K, V, S> ShardedMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shards: usize, hasher: S) -> Self {
        let n = shards.max(1).next_power_of_two();
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            v.push(Shard {
                inner: RwLock::new(HashMap::with_hasher(hasher.clone())),
            });
        }
        Self {
            shards: v.into_boxed_slice(),
            hasher,
            shard_mask: n - 1,
        }
    }

    #[inline]
    fn hash<Q: Hash + ?Sized>(&self, k: &Q) -> u64 {
        let mut h = self.hasher.build_hasher();
        k.hash(&mut h);
        h.finish()
    }

    // Use the high bits for shard selection. hashbrown indexes its buckets
    // from the low bits, so pulling shard index from elsewhere avoids
    // correlated collisions inside each shard.
    #[inline]
    fn shard_for(&self, hash: u64) -> usize {
        (hash >> 32) as usize & self.shard_mask
    }

    #[inline]
    fn read(&self, idx: usize) -> RwLockReadGuard<'_, HashMap<K, V, S>> {
        self.shards[idx].inner.read()
    }

    #[inline]
    fn write(&self, idx: usize) -> RwLockWriteGuard<'_, HashMap<K, V, S>> {
        self.shards[idx].inner.write()
    }

    pub fn insert(&self, key: K, value: V) -> Option<V> {
        let hash = self.hash(&key);
        let mut g = self.write(self.shard_for(hash));
        match g.raw_entry_mut().from_key_hashed_nocheck(hash, &key) {
            RawEntryMut::Occupied(mut e) => Some(e.insert(value)),
            RawEntryMut::Vacant(e) => {
                e.insert_hashed_nocheck(hash, key, value);
                None
            }
        }
    }

    pub fn remove<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        let mut g = self.write(self.shard_for(hash));
        match g.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(e) => Some(e.remove()),
            RawEntryMut::Vacant(_) => None,
        }
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        let g = self.read(self.shard_for(hash));
        g.raw_entry().from_key_hashed_nocheck(hash, key).is_some()
    }

    pub fn get<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        V: Clone,
    {
        let hash = self.hash(key);
        let g = self.read(self.shard_for(hash));
        g.raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| v.clone())
    }

    pub fn with<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&V) -> R,
    {
        let hash = self.hash(key);
        let g = self.read(self.shard_for(hash));
        g.raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| f(v))
    }

    pub fn with_mut<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&mut V) -> R,
    {
        let hash = self.hash(key);
        let mut g = self.write(self.shard_for(hash));
        match g.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(mut e) => Some(f(e.get_mut())),
            RawEntryMut::Vacant(_) => None,
        }
    }

    pub fn upsert<F>(&self, key: K, default: V, f: F)
    where
        F: FnOnce(&mut V),
    {
        let hash = self.hash(&key);
        let mut g = self.write(self.shard_for(hash));
        match g.raw_entry_mut().from_key_hashed_nocheck(hash, &key) {
            RawEntryMut::Occupied(mut e) => f(e.get_mut()),
            RawEntryMut::Vacant(e) => {
                e.insert_hashed_nocheck(hash, key, default);
            }
        }
    }

    pub fn len(&self) -> usize {
        self.shards.iter().map(|s| s.inner.read().len()).sum()
    }

    pub fn clear(&self) {
        for s in self.shards.iter() {
            s.inner.write().clear();
        }
    }
}
```

What this buys, qualitatively:

- **Reader throughput** scales much closer to linearly with cores because shard locks no longer share cache lines, and `parking_lot`'s reader fast path is a single CAS on a `usize` instead of a syscall-capable RwLock.
- **Per-shard memory** drops noticeably: parking_lot's `RwLock<T>` is roughly `T + 1 byte` (rounded for alignment) versus std's much larger layout, and `hashbrown` uses ~1.5 bytes of overhead per slot vs. std's heavier raw table representation. The 64-byte alignment per shard adds back some bytes, but with ~4×CPU shards it's tens of KB at most.
- **Read latency** drops by one hash computation per operation, which matters when keys are large (long strings, structured types).

For workloads that are read-overwhelming (think 100:1 reads to writes, like a config or routing table), even a contended `RwLock` is too much. The right shape there is RCU via `arc-swap`:

```rust
use arc_swap::ArcSwap;
use std::sync::{Arc, Mutex};

pub struct RcuMap<K, V, S = RandomState> {
    snapshot: ArcSwap<HashMap<K, V, S>>,
    writer: Mutex<()>, // serialize writers; readers never touch this
    hasher: S,
}

impl<K: Hash + Eq + Clone, V: Clone, S: BuildHasher + Clone> RcuMap<K, V, S> {
    pub fn get(&self, key: &K) -> Option<V> {
        // Lock-free read: an Arc clone, an atomic load, a hash lookup.
        self.snapshot.load().get(key).cloned()
    }

    pub fn insert(&self, key: K, value: V) {
        let _g = self.writer.lock().unwrap();
        let mut next = (**self.snapshot.load()).clone(); // copy current
        next.insert(key, value);
        self.snapshot.store(Arc::new(next));
    }
}
```

Reads are wait-free (no atomic RMW on a shared counter, just a `load`), at the cost of writes copying the map. Use this when writes are rare or batched, and the sharded `RwLock` design otherwise.
